1: import test from 'node:test';
2: import assert from 'node:assert/strict';
3: import { createRequire } from 'node:module';
4: import { resolve } from 'node:path';
5: import { readFileSync } from 'node:fs';
6: const require = createRequire(resolve(process.env.SUFFICE_WORKSPACE, 'src/package.json'));
7: const semver = require('./index.js');
8: const fixture = name => require(`./test/fixtures/${name}.js`);
9: test('upstream range parsing fixtures', () => {
10:   for (const [range, expected, options] of fixture('range-parse')) assert.equal(semver.validRange(range, options), expected, JSON.stringify([range,options]));
11: });
12: test('upstream range inclusion fixtures', () => {
13:   for (const [range, version, options] of fixture('range-include')) assert.equal(semver.satisfies(version,range,options),true,JSON.stringify([range,version,options]));
14: });
15: test('upstream range exclusion fixtures', () => {
16:   for (const [range, version, options] of fixture('range-exclude')) assert.equal(semver.satisfies(version,range,options),false,JSON.stringify([range,version,options]));
17: });
18: test('upstream increment fixtures and object nonmutation', () => {
19:   for (const [pre, what, expected, options, id, base] of fixture('increments')) {
20:     assert.equal(semver.inc(pre,what,options,id,base),expected,JSON.stringify([pre,what,options,id,base]));
21:     const parsed=semver.parse(pre,options);
22:     if(parsed){const before=JSON.stringify(parsed);semver.inc(parsed,what,options,id,base);assert.equal(JSON.stringify(parsed),before);}
23:   }
24: });
25: test('upstream version comparison fixtures', () => {
26:   for (const [a,b,options] of fixture('comparisons')) {assert.equal(semver.gt(a,b,options),true);assert.equal(semver.lt(b,a,options),true);assert.equal(semver.eq(a,b,options),false);}
27: });
28: test('upstream version equality fixtures', () => {
29:   for (const [a,b,options] of fixture('equality')) assert.equal(semver.eq(a,b,options),true,JSON.stringify([a,b,options]));
30: });
31: test('upstream subset fixtures and range object inputs',()=>{
32:   const cases=JSON.parse(readFileSync(resolve(process.env.SUFFICE_WORKSPACE,'tests/upstream-subset-cases.json'),'utf8'));
33:   for(const [sub,dom,expected,options]of cases){
34:     assert.equal(semver.subset(sub,dom,options),expected,JSON.stringify([sub,dom,options]));
35:     assert.equal(semver.subset(new semver.Range(sub,options),new semver.Range(dom,options),options),expected);
36:   }
37: });
